  UNION ALL SELECT 'ENARTIS','enartistan fp','wine_bench','Wine tannin bench trial','Color/protein stabilization during maturation','red,rose','aging','bench_trial',5,15,'g/hL','Official wine range','Dissolve 1:10 in water, wine or must while mixing continuously.','Add only after a recorded laboratory and sensory trial selects the rate.','Verified wine volume, current chemistry, stability review and recorded trial','ph,total_acidity',30,'Check filterability plus protein and colloidal stability near bottling.',168,'https://www.enartis.com/datasheets/TECHNICAL-DATA-SHEET/EN/TDS-EN-TanFp.pdf','revision 2 June 2020'
  UNION ALL SELECT 'ENARTIS','enartistan ft','must','Must tannin program','Antioxidant, clarification, protein/color stability and structure support','any','must,fermentation','crusher_or_fermentation',10,20,'g/hL','Official must range','Dissolve and homogenize according to the current sheet.','Add only after the purpose and exact rate are selected.','Verified volume, chemistry, fruit condition and phenolic objective','ph,total_acidity,potential_alcohol',7,'Finished wine uses a separate 3-10 g/hL bench-trial protocol.',NULL,'https://www.enartis.com/datasheets/TECHNICAL-DATA-SHEET/EN/TDS-EN-TanFt.pdf','current sheet accessed 2026-09-16'
